-- =====================================================================
-- Aikido Shinjukai Admin System: PostgreSQL schema
-- Target: PostgreSQL 15+ (Supabase default). Run in the Supabase SQL Editor.
--
-- Conventions
--  * Primary keys are UUIDs generated by the database.
--  * Money is stored as integer cents (amount_cents), currency defaults to SGD.
--  * Times of day are minutes from midnight (19:30 = 1170). weekday: 0 = Sunday ... 6 = Saturday.
--  * Timestamps are timestamptz (stored in UTC).
--  * Files are NOT stored in the database; stored_files keeps the storage key + metadata.
--  * Invoice "overdue" is computed (see view invoice_balances), not stored.
-- =====================================================================

-- Reset: uncomment to wipe the public schema before rebuilding.
-- WARNING: deletes all tables and data in public.
/*
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON SCHEMA public TO postgres, service_role;
*/

------------------------------------------------------------------- Enums
CREATE TYPE user_role            AS ENUM ('ADMIN', 'STUDENT');
CREATE TYPE session_status       AS ENUM ('SCHEDULED', 'COMPLETED', 'CANCELLED');
CREATE TYPE grading_type         AS ENUM ('MASS', 'PRIVATE');
CREATE TYPE grading_outcome      AS ENUM ('GRADED', 'NOT_GRADED');   -- AS-10: replaces PASS / FAIL
CREATE TYPE invoice_status       AS ENUM ('UNPAID', 'PARTIALLY_PAID', 'PAID', 'VOID');
CREATE TYPE payment_channel      AS ENUM ('STRIPE', 'WHATSAPP', 'EMAIL', 'CASH', 'BANK_TRANSFER', 'OTHER');
CREATE TYPE payment_status       AS ENUM ('PENDING', 'COMPLETED', 'FAILED');
CREATE TYPE proof_status         AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE document_type        AS ENUM ('WAIVER', 'FORM', 'CERTIFICATE', 'OTHER');
CREATE TYPE notification_type    AS ENUM ('GRADING_NOTICE', 'PROMOTION_CONGRATS', 'PAYMENT_REMINDER', 'OVERDUE_NOTICE', 'RECEIPT', 'OTHER');
CREATE TYPE notification_channel AS ENUM ('EMAIL', 'PUSH');
CREATE TYPE notification_status  AS ENUM ('PENDING', 'SENT', 'FAILED');

-- ---------------------------------------------------------------- Accounts
CREATE TABLE users (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email          text        NOT NULL UNIQUE,
  password_hash  text        NOT NULL,
  role           user_role   NOT NULL,
  is_active      boolean     NOT NULL DEFAULT true,
  last_login_at  timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE push_tokens (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token       text        NOT NULL UNIQUE,
  platform    text        NOT NULL,              -- 'ios' | 'android'
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_push_tokens_user ON push_tokens(user_id);

-- ---------------------------------------------------------------- Centres, venues, ranks
CREATE TABLE centres (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text        NOT NULL UNIQUE,
  address     text,
  email       text,
  phone       text,
  is_hq       boolean     NOT NULL DEFAULT false,      -- AS-10: gradings are held only at HQ
  is_active   boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
-- At most one centre can be HQ.
CREATE UNIQUE INDEX uq_centres_single_hq ON centres (is_hq) WHERE is_hq;

CREATE TABLE venues (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  centre_id   uuid        NOT NULL REFERENCES centres(id),
  name        text        NOT NULL,
  capacity    integer     NOT NULL CHECK (capacity > 0),
  is_active   boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (centre_id, name)
);
CREATE INDEX idx_venues_centre ON venues(centre_id);

-- Ordered belt ladder. Higher rank_order = higher rank.
CREATE TABLE ranks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text    NOT NULL UNIQUE,
  rank_order  integer NOT NULL UNIQUE,
  colour      text
);

-- ---------------------------------------------------------------- People
CREATE TABLE students (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid        UNIQUE REFERENCES users(id),
  centre_id        uuid        NOT NULL REFERENCES centres(id),
  current_rank_id  uuid        NOT NULL REFERENCES ranks(id),
  rank_since       timestamptz NOT NULL DEFAULT now(),   -- for time-in-rank checks
  first_name       text        NOT NULL,
  last_name        text        NOT NULL,
  email            text        NOT NULL UNIQUE,
  phone            text,
  date_of_birth    date,
  guardian_name    text,                                  -- for minors
  guardian_phone   text,
  joined_at        timestamptz NOT NULL DEFAULT now(),
  is_active        boolean     NOT NULL DEFAULT true,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_students_centre ON students(centre_id);
CREATE INDEX idx_students_rank   ON students(current_rank_id);
CREATE INDEX idx_students_name   ON students(last_name, first_name);

-- Instructors are records only (no login). access_token powers the read-only link (AS-20).
CREATE TABLE instructors (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name            text        NOT NULL,
  email           text,
  phone           text,
  rank_id         uuid        REFERENCES ranks(id),
  qualifications  text,
  access_token    text        NOT NULL UNIQUE DEFAULT replace(gen_random_uuid()::text, '-', ''),
  is_active       boolean     NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

-- An instructor may teach at more than one centre.
CREATE TABLE instructor_centres (
  instructor_id  uuid NOT NULL REFERENCES instructors(id) ON DELETE CASCADE,
  centre_id      uuid NOT NULL REFERENCES centres(id)     ON DELETE CASCADE,
  PRIMARY KEY (instructor_id, centre_id)
);
CREATE INDEX idx_instructor_centres_centre ON instructor_centres(centre_id);

-- Recurring weekly availability.
CREATE TABLE instructor_availability (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  instructor_id  uuid     NOT NULL REFERENCES instructors(id) ON DELETE CASCADE,
  weekday        smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  start_minute   integer  NOT NULL CHECK (start_minute BETWEEN 0 AND 1440),
  end_minute     integer  NOT NULL CHECK (end_minute BETWEEN 0 AND 1440),
  CHECK (end_minute > start_minute)
);
CREATE INDEX idx_availability_instructor ON instructor_availability(instructor_id, weekday);

-- One-off unavailable dates (leave, travel, etc.).
CREATE TABLE instructor_unavailable_dates (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  instructor_id  uuid NOT NULL REFERENCES instructors(id) ON DELETE CASCADE,
  date           date NOT NULL,
  reason         text,
  UNIQUE (instructor_id, date)
);

-- ---------------------------------------------------------------- Scheduling
CREATE TABLE terms (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  centre_id   uuid        NOT NULL REFERENCES centres(id),
  name        text        NOT NULL,
  start_date  date        NOT NULL,
  end_date    date        NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (end_date >= start_date)
);
CREATE INDEX idx_terms_centre_start ON terms(centre_id, start_date);

-- Weekly recurring definition of a class.
CREATE TABLE class_templates (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  centre_id      uuid        NOT NULL REFERENCES centres(id),      -- AS-4: a class belongs to a centre
  instructor_id  uuid        REFERENCES instructors(id),           -- AS-6: one fixed instructor
  term_id        uuid        REFERENCES terms(id),                 -- legacy, no longer used
  venue_id       uuid        REFERENCES venues(id),                -- legacy, no longer used
  level_rank_id  uuid        REFERENCES ranks(id),    -- optional: class aimed at a rank
  name           text        NOT NULL,
  weekday        smallint    NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  start_minute   integer     NOT NULL CHECK (start_minute BETWEEN 0 AND 1440),
  end_minute     integer     NOT NULL CHECK (end_minute BETWEEN 0 AND 1440),
  created_at     timestamptz NOT NULL DEFAULT now(),
  CHECK (end_minute > start_minute)
);
CREATE INDEX idx_class_templates_term  ON class_templates(term_id);
CREATE INDEX idx_class_templates_venue ON class_templates(venue_id, weekday);
CREATE INDEX idx_class_templates_centre     ON class_templates(centre_id, weekday);
CREATE INDEX idx_class_templates_instructor ON class_templates(instructor_id);

CREATE TABLE class_template_instructors (
  template_id    uuid NOT NULL REFERENCES class_templates(id) ON DELETE CASCADE,
  instructor_id  uuid NOT NULL REFERENCES instructors(id)     ON DELETE CASCADE,
  PRIMARY KEY (template_id, instructor_id)
);

-- Dated occurrence generated from a template. Used for the timetable and conflict checks.
CREATE TABLE class_sessions (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  template_id  uuid           NOT NULL REFERENCES class_templates(id) ON DELETE CASCADE,
  venue_id     uuid           REFERENCES venues(id),            -- legacy, no longer used
  starts_at    timestamptz    NOT NULL,
  ends_at      timestamptz    NOT NULL,
  status       session_status NOT NULL DEFAULT 'SCHEDULED',
  note         text,
  UNIQUE (template_id, starts_at),
  CHECK (ends_at > starts_at)
);
CREATE INDEX idx_class_sessions_venue_time ON class_sessions(venue_id, starts_at);
CREATE INDEX idx_class_sessions_start      ON class_sessions(starts_at);

CREATE TABLE class_session_instructors (
  session_id     uuid NOT NULL REFERENCES class_sessions(id) ON DELETE CASCADE,
  instructor_id  uuid NOT NULL REFERENCES instructors(id)    ON DELETE CASCADE,
  PRIMARY KEY (session_id, instructor_id)
);
CREATE INDEX idx_session_instructors_instructor ON class_session_instructors(instructor_id);

-- ---------------------------------------------------------------- Grading and promotion
CREATE TABLE grading_sessions (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  centre_id   uuid           NOT NULL REFERENCES centres(id),
  venue_id    uuid           REFERENCES venues(id),             -- legacy: gradings are at HQ, no room needed
  type        grading_type   NOT NULL,
  status      session_status NOT NULL DEFAULT 'SCHEDULED',
  title       text,
  starts_at   timestamptz    NOT NULL,
  ends_at     timestamptz    NOT NULL,
  notes       text,
  created_at  timestamptz    NOT NULL DEFAULT now(),
  updated_at  timestamptz    NOT NULL DEFAULT now(),
  CHECK (ends_at > starts_at)
);
CREATE INDEX idx_gradings_centre_time ON grading_sessions(centre_id, starts_at);
CREATE INDEX idx_gradings_venue_time  ON grading_sessions(venue_id, starts_at);

-- Which belt levels a grading session tests.
CREATE TABLE grading_ranks_tested (
  grading_session_id  uuid NOT NULL REFERENCES grading_sessions(id) ON DELETE CASCADE,
  rank_id             uuid NOT NULL REFERENCES ranks(id),
  PRIMARY KEY (grading_session_id, rank_id)
);

CREATE TABLE grading_examiners (
  grading_session_id  uuid NOT NULL REFERENCES grading_sessions(id) ON DELETE CASCADE,
  instructor_id       uuid NOT NULL REFERENCES instructors(id),
  PRIMARY KEY (grading_session_id, instructor_id)
);
CREATE INDEX idx_grading_examiners_instructor ON grading_examiners(instructor_id);

-- A student registered for a grading. The result is stored on the same row.
CREATE TABLE grading_candidates (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  grading_session_id  uuid            NOT NULL REFERENCES grading_sessions(id) ON DELETE CASCADE,
  student_id          uuid            NOT NULL REFERENCES students(id),
  from_rank_id        uuid            NOT NULL REFERENCES ranks(id),   -- rank when registered
  graded_for_rank_id  uuid            REFERENCES ranks(id),            -- AS-10: rank graded for
  instructor_id       uuid            REFERENCES instructors(id),      -- AS-10: grading instructor
  outcome             grading_outcome,                                  -- NULL until recorded
  remarks             text,
  result_recorded_at  timestamptz,
  created_at          timestamptz     NOT NULL DEFAULT now(),
  UNIQUE (grading_session_id, student_id)
);
CREATE INDEX idx_candidates_student ON grading_candidates(student_id);

-- Rank history (AS-8). Ranks change only when an admin updates them, never automatically.
-- candidate_id is optional (NULL for manual changes); UNIQUE still allows many NULLs.
CREATE TABLE promotion_history (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id    uuid        NOT NULL REFERENCES students(id),
  candidate_id  uuid        UNIQUE REFERENCES grading_candidates(id),
  from_rank_id  uuid        NOT NULL REFERENCES ranks(id),
  to_rank_id    uuid        NOT NULL REFERENCES ranks(id),
  promoted_at   timestamptz NOT NULL DEFAULT now(),
  changed_by_id uuid        REFERENCES users(id),     -- admin who made the change
  note          text
);
CREATE INDEX idx_promotions_student ON promotion_history(student_id);
CREATE INDEX idx_promotions_date    ON promotion_history(promoted_at);

-- ---------------------------------------------------------------- Fees, invoices, payments
CREATE TABLE fee_items (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  centre_id     uuid        REFERENCES centres(id),      -- NULL = applies to all centres
  term_id       uuid        REFERENCES terms(id),
  name          text        NOT NULL,
  description   text,
  amount_cents  integer     NOT NULL CHECK (amount_cents >= 0),
  currency      text        NOT NULL DEFAULT 'SGD',
  due_date      date        NOT NULL,
  is_active     boolean     NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_fee_items_centre ON fee_items(centre_id);

CREATE SEQUENCE invoice_number_seq START 1;

CREATE TABLE invoices (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_number  text           NOT NULL UNIQUE
                  DEFAULT ('INV-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('invoice_number_seq')::text, 4, '0')),
  student_id      uuid           NOT NULL REFERENCES students(id),
  fee_item_id     uuid           NOT NULL REFERENCES fee_items(id),
  description     text           NOT NULL,                -- snapshot of fee name at issue time
  amount_cents    integer        NOT NULL CHECK (amount_cents >= 0),  -- snapshot of amount
  currency        text           NOT NULL DEFAULT 'SGD',
  due_date        date           NOT NULL,
  status          invoice_status NOT NULL DEFAULT 'UNPAID',
  issued_at       timestamptz    NOT NULL DEFAULT now(),
  paid_at         timestamptz,
  UNIQUE (student_id, fee_item_id)                        -- prevents duplicate invoices
);
CREATE INDEX idx_invoices_status_due ON invoices(status, due_date);
CREATE INDEX idx_invoices_student    ON invoices(student_id);

-- AS-9: packages sold by HQ (no admin screen, rows are maintained in the database).
CREATE TABLE packages (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name            text        NOT NULL UNIQUE,
  sessions_total  integer     NOT NULL CHECK (sessions_total > 0),
  validity_weeks  integer     NOT NULL CHECK (validity_weeks > 0),
  price_cents     integer     NOT NULL CHECK (price_cents >= 0),
  currency        text        NOT NULL DEFAULT 'SGD',
  is_active       boolean     NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- AS-12: a payment belongs to a student and a package. invoice_id is kept only for old rows.
-- Status is COMPLETED (shown as Successful) or FAILED. paid_at is the exact payment time.
-- Each payment method has its own sequence, producing references such as BT-00001 and C-00001.
CREATE SEQUENCE payment_reference_bank_transfer_seq;
CREATE SEQUENCE payment_reference_cash_seq;
CREATE SEQUENCE payment_reference_stripe_seq;
CREATE SEQUENCE payment_reference_whatsapp_seq;
CREATE SEQUENCE payment_reference_email_seq;
CREATE SEQUENCE payment_reference_other_seq;

CREATE TABLE payments (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id              uuid            REFERENCES invoices(id),
  student_id              uuid            REFERENCES students(id),
  package_id              uuid            REFERENCES packages(id),
  amount_cents            integer         NOT NULL CHECK (amount_cents > 0),
  channel                 payment_channel NOT NULL,
  status                  payment_status  NOT NULL DEFAULT 'COMPLETED',
  paid_at                 timestamptz     NOT NULL DEFAULT now(),
  reference               text            NOT NULL UNIQUE,
  notes                   text,
  recorded_by_id          uuid            REFERENCES users(id),   -- admin who logged a manual payment
  stripe_checkout_session text            UNIQUE,
  stripe_payment_intent   text            UNIQUE,
  created_at              timestamptz     NOT NULL DEFAULT now(),
  CONSTRAINT chk_payments_status CHECK (status IN ('COMPLETED', 'FAILED')),
  CONSTRAINT chk_payments_owner  CHECK (invoice_id IS NOT NULL OR student_id IS NOT NULL)
);

-- BEFORE INSERT runs before a new row is saved. NEW is the row being inserted.
-- nextval() takes the next number from the sequence for that payment method.
-- lpad(..., 5, '0') pads the number to five digits, for example 12 -> 00012.
CREATE FUNCTION assign_payment_reference() RETURNS trigger AS $$
BEGIN
  NEW.reference := CASE NEW.channel
    WHEN 'BANK_TRANSFER' THEN 'BT-' || lpad(nextval('payment_reference_bank_transfer_seq')::text, 5, '0')
    WHEN 'CASH'          THEN 'C-'  || lpad(nextval('payment_reference_cash_seq')::text, 5, '0')
    WHEN 'STRIPE'        THEN 'ST-' || lpad(nextval('payment_reference_stripe_seq')::text, 5, '0')
    WHEN 'WHATSAPP'      THEN 'WA-' || lpad(nextval('payment_reference_whatsapp_seq')::text, 5, '0')
    WHEN 'EMAIL'         THEN 'EM-' || lpad(nextval('payment_reference_email_seq')::text, 5, '0')
    ELSE                      'OT-' || lpad(nextval('payment_reference_other_seq')::text, 5, '0')
  END;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER payments_assign_reference
BEFORE INSERT ON payments
FOR EACH ROW EXECUTE FUNCTION assign_payment_reference();

CREATE INDEX idx_payments_invoice   ON payments(invoice_id);
CREATE INDEX idx_payments_student   ON payments(student_id);
CREATE INDEX idx_payments_reference ON payments(reference);

-- A package a student owns. It exists only after a Successful payment (payment_id is required and unique).
CREATE TABLE student_packages (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id      uuid        NOT NULL REFERENCES students(id),
  package_id      uuid        NOT NULL REFERENCES packages(id),
  payment_id      uuid        NOT NULL UNIQUE REFERENCES payments(id),
  name            text        NOT NULL,
  sessions_total  integer     NOT NULL CHECK (sessions_total > 0),
  purchased_at    timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_student_packages_student ON student_packages(student_id, expires_at);

-- One row per session attended. Sessions used = row count. One per student per Singapore day.
CREATE TABLE attendance (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id          uuid        NOT NULL REFERENCES students(id),
  student_package_id  uuid        NOT NULL REFERENCES student_packages(id) ON DELETE CASCADE,
  attended_at         timestamptz NOT NULL DEFAULT now(),
  attended_on         date        NOT NULL DEFAULT ((now() AT TIME ZONE 'Asia/Singapore')::date),
  UNIQUE (student_id, attended_on)
);
CREATE INDEX idx_attendance_package ON attendance(student_package_id);
CREATE INDEX idx_payments_paid_at ON payments(paid_at);
CREATE INDEX idx_payments_channel ON payments(channel);

-- Each Stripe webhook event ID is stored once, so replayed events are ignored.
CREATE TABLE stripe_events (
  id            text PRIMARY KEY,                        -- Stripe event ID (evt_...)
  type          text        NOT NULL,
  processed_at  timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- Files and documents
-- Metadata for a file held in object storage (Supabase Storage / S3). Bytes are not in Postgres.
CREATE TABLE stored_files (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  storage_key     text        NOT NULL UNIQUE,           -- path/key in the storage bucket
  file_name       text        NOT NULL,
  mime_type       text        NOT NULL,
  size_bytes      integer     NOT NULL CHECK (size_bytes >= 0),
  uploaded_by_id  uuid        REFERENCES users(id),
  created_at      timestamptz NOT NULL DEFAULT now()
);

-- Student-uploaded proof of a bank/WhatsApp transfer (AS-31).
CREATE TABLE payment_proofs (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id      uuid         NOT NULL REFERENCES invoices(id),
  student_id      uuid         NOT NULL REFERENCES students(id),
  file_id         uuid         NOT NULL UNIQUE REFERENCES stored_files(id),
  payment_id      uuid         UNIQUE REFERENCES payments(id),   -- set when approved
  status          proof_status NOT NULL DEFAULT 'PENDING',
  student_note    text,
  review_note     text,
  reviewed_by_id  uuid         REFERENCES users(id),
  reviewed_at     timestamptz,
  created_at      timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX idx_proofs_status  ON payment_proofs(status);
CREATE INDEX idx_proofs_invoice ON payment_proofs(invoice_id);

CREATE TABLE documents (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id  uuid          NOT NULL REFERENCES students(id),
  file_id     uuid          NOT NULL UNIQUE REFERENCES stored_files(id),
  type        document_type NOT NULL,
  title       text          NOT NULL,
  created_at  timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX idx_documents_student_type ON documents(student_id, type);
CREATE INDEX idx_documents_created      ON documents(created_at);

-- ---------------------------------------------------------------- Notifications and settings
-- Every email/push attempt. dedupe_key stops the same reminder being sent twice,
-- e.g. 'reminder:<invoice_id>:3d' or 'overdue:<invoice_id>:7d'.
CREATE TABLE notification_log (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  student_id     uuid                 REFERENCES students(id),
  invoice_id     uuid                 REFERENCES invoices(id),
  candidate_id   uuid                 REFERENCES grading_candidates(id),
  type           notification_type    NOT NULL,
  channel        notification_channel NOT NULL DEFAULT 'EMAIL',
  status         notification_status  NOT NULL DEFAULT 'PENDING',
  recipient      text                 NOT NULL,
  subject        text,
  error_message  text,
  attempts       integer              NOT NULL DEFAULT 0,
  dedupe_key     text                 UNIQUE,
  sent_at        timestamptz,
  created_at     timestamptz          NOT NULL DEFAULT now()
);
CREATE INDEX idx_notifications_status_type ON notification_log(status, type);
CREATE INDEX idx_notifications_created     ON notification_log(created_at);

CREATE TABLE email_templates (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  type        notification_type NOT NULL UNIQUE,
  subject     text              NOT NULL,
  body        text              NOT NULL,                -- supports {{name}}, {{amount}}, {{dueDate}}, {{belt}}
  updated_at  timestamptz       NOT NULL DEFAULT now()
);

-- Key-value settings, e.g. reminderDaysBefore = 3, overdueIntervalsDays = [1, 7, 14].
CREATE TABLE settings (
  key         text PRIMARY KEY,
  value       jsonb       NOT NULL,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE audit_log (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid        REFERENCES users(id),
  action       text        NOT NULL,                     -- e.g. 'PROMOTE_STUDENT', 'RECORD_PAYMENT'
  entity_type  text        NOT NULL,
  entity_id    text        NOT NULL,
  before       jsonb,
  after        jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_entity  ON audit_log(entity_type, entity_id);
CREATE INDEX idx_audit_created ON audit_log(created_at);

-- ---------------------------------------------------------------- Automatic updated_at
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['users','centres','venues','students','instructors',
                           'grading_sessions','email_templates','settings']
  LOOP
    EXECUTE format('CREATE TRIGGER trg_%I_updated_at BEFORE UPDATE ON %I
                    FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t, t);
  END LOOP;
END $$;

-- ---------------------------------------------------------------- Helpful view
-- Invoice balances and computed overdue flag, for the payment dashboard and reminders.
CREATE VIEW invoice_balances AS
SELECT
  i.id,
  i.invoice_number,
  i.student_id,
  i.amount_cents,
  COALESCE(SUM(p.amount_cents) FILTER (WHERE p.status = 'COMPLETED'), 0)               AS paid_cents,
  i.amount_cents - COALESCE(SUM(p.amount_cents) FILTER (WHERE p.status = 'COMPLETED'), 0) AS outstanding_cents,
  i.due_date,
  i.status,
  (i.status IN ('UNPAID', 'PARTIALLY_PAID') AND i.due_date < CURRENT_DATE)            AS is_overdue
FROM invoices i
LEFT JOIN payments p ON p.invoice_id = i.id
GROUP BY i.id;

-- ---------------------------------------------------------------- Security
-- All access goes through the Express API (which connects as the database owner),
-- so turn on Row Level Security with no policies. This blocks access via Supabase's public API keys.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.tablename);
  END LOOP;
END $$;

-- Views ignore RLS by default (they run with the owner's rights), so make the view
-- respect the caller's permissions too. Requires PostgreSQL 15+.
ALTER VIEW invoice_balances SET (security_invoker = true);

